// Polls state that driver callbacks and other fibers update while the run is active.
const sleepWhile = (condition: () => boolean, intervalMs = 1) =>
  Effect.gen(function* () {
    while (condition()) {
      yield* Effect.sleep(intervalMs);
    }
  });
