describe("direct escape sprint directions", () => {
  it("does not sprint along a ledge with a drop beside it", () => {
    const player = { x: 0.5, y: 64, z: 0.5, dimension: "minecraft:overworld" } as const;
    // A one-block-wide ledge heading east, three blocks above the ground
    // on both sides.
    const columns = Array.from({ length: 21 }, (_, x) =>
      [-1, 0, 1].map((z) => ({
        x: x - 2,
        z,
        loaded: true,
        surfaceY: z === 0 ? 63 : 60,
        blockId: "minecraft:grass_block",
        biomeId: "minecraft:plains",
        skyLight: 15,
        blockLight: 0,
      })),
    ).flat();

    expect(
      selectSafeDirectEscapeDirection(
        columns,
        player,
        { x: 1, z: 0 },
        [],
        8,
        DIRECT_ESCAPE_MINIMUM_LATERAL_HALF_WIDTH,
      ),
    ).toBeUndefined();
    expect(
      selectSafeDirectEscapeDirection(
        // oxlint-disable-next-line oxc/no-map-spread -- the copy keeps the shared columns fixture unchanged
        columns.map((column) => ({ ...column, surfaceY: 63 })),
        player,
        { x: 1, z: 0 },
        [],
        8,
        DIRECT_ESCAPE_MINIMUM_LATERAL_HALF_WIDTH,
      ),
    ).toEqual({ x: 1, z: 0 });
  });
});

describe("direct threat escape corridors", () => {
  const player = {
    x: -254,
    y: 64,
    z: 16,
    dimension: "minecraft:overworld",
  } as const;
  const skeleton = {
    connectionEpoch: "epoch-1",
    networkId: 29_286,
    entityType: "minecraft:skeleton",
    position: {
      x: -253,
      y: 64,
      z: 23,
      dimension: "minecraft:overworld",
    },
    velocity: { x: 0, y: 0, z: 0 },
    alive: true,
    health: 20,
    observedAt: "2026-08-30T06:12:49.162Z",
  } as const satisfies BeatGameEntityObservation;

  it("rejects the live sprint direction that initially approached a skeleton", () => {
    expect(hasNonRegressingThreatEscapeCorridor(player, { x: 1, z: 1 }, [skeleton], 18)).toBe(
      false,
    );
  });

  it("accepts a corridor that continuously opens distance from the skeleton", () => {
    expect(
      hasNonRegressingThreatEscapeCorridor(
        player,
        {
          x: player.x - skeleton.position.x,
          z: player.z - skeleton.position.z,
        },
        [skeleton],
        18,
      ),
    ).toBe(true);
  });
});

describe("inventory discards", () => {
  it("drops netherrack beyond the building reserve a stack at a time", () => {
    // As in a live run whose full inventory blocked a pickaxe craft.
    expect(
      selectInventoryDiscard({
        "minecraft:netherrack": 726,
        "minecraft:stone_sword": 1,
        "minecraft:cooked_porkchop": 6,
      }),
    ).toEqual({ itemId: "minecraft:netherrack", count: 64 });
    expect(selectInventoryDiscard({ "minecraft:netherrack": 100 })).toEqual({
      itemId: "minecraft:netherrack",
      count: 36,
    });
  });

  it("frees slots held by Overworld pickups that nothing uses", () => {
    // As in a live run that reached the Nether too full to craft gold boots.
    expect(
      selectInventoryDiscard({
        "minecraft:wildflowers": 22,
        "minecraft:cobblestone": 64,
        "minecraft:cooked_porkchop": 4,
        "minecraft:flint_and_steel": 1,
      }),
    ).toEqual({ itemId: "minecraft:wildflowers", count: 22 });
    expect(
      selectInventoryDiscard({
        "minecraft:fishing_rod": 1,
        "minecraft:cobblestone": 64,
      }),
    ).toEqual({ itemId: "minecraft:fishing_rod", count: 1 });
  });

  it("frees slots held by everything a long run picked up on the way", () => {
    // The inventory a live bot held when its gold boots failed 54 times.
    const counts: Record<string, number> = {
      "minecraft:arrow": 8,
      "minecraft:black_wool": 3,
      "minecraft:blaze_rod": 6,
      "minecraft:bow": 1,
      "minecraft:cobblestone": 58,
      "minecraft:firefly_bush": 1,
      "minecraft:flint": 9,
      "minecraft:glowstone_dust": 14,
      "minecraft:gold_nugget": 14,
      "minecraft:music_disc_lava_chicken": 1,
      "minecraft:nautilus_shell": 1,
      "minecraft:nether_brick_fence": 4,
      "minecraft:phantom_membrane": 1,
      "minecraft:white_wool": 5,
      "minecraft:wither_skeleton_skull": 1,
    };
    const discarded: string[] = [];
    for (let discard = selectInventoryDiscard(counts); discard !== undefined;) {
      discarded.push(discard.itemId);
      counts[discard.itemId] = 0;
      discard = selectInventoryDiscard(counts);
    }

    expect(discarded.toSorted()).toEqual([
      "minecraft:firefly_bush",
      "minecraft:glowstone_dust",
      "minecraft:music_disc_lava_chicken",
      "minecraft:nautilus_shell",
      "minecraft:nether_brick_fence",
      "minecraft:phantom_membrane",
      "minecraft:wither_skeleton_skull",
    ]);
  });

  it("frees slots held by Nether junk", () => {
    // As in a live run whose inventory was full of Nether plants and magma,
    // so it could not make room for food.
    const counts = {
      "minecraft:magma_block": 80,
      "minecraft:nether_wart_block": 12,
      "minecraft:netherrack": 64,
      "minecraft:stone_sword": 1,
    };
    expect(selectInventoryDiscard(counts)).toEqual({
      itemId: "minecraft:nether_wart_block",
      count: 12,
    });
    expect(selectInventoryDiscard({ ...counts, "minecraft:nether_wart_block": 0 })).toEqual({
      itemId: "minecraft:magma_block",
      count: 80,
    });
  });

  it("frees slots held by basalt delta rock", () => {
    // As in a live run whose inventory filled up in a basalt delta.
    expect(
      selectInventoryDiscard({
        "minecraft:basalt": 332,
        "minecraft:blackstone": 56,
        "minecraft:netherrack": 64,
        "minecraft:stone_sword": 1,
      }),
    ).toEqual({ itemId: "minecraft:basalt", count: 64 });
    expect(selectInventoryDiscard({ "minecraft:calcite": 15, "minecraft:netherrack": 64 })).toEqual(
      { itemId: "minecraft:calcite", count: 15 },
    );
  });

  it("keeps a cobblestone reserve for pickaxes", () => {
    // As in a live run that threw away all its cobblestone and then had no
    // stone for pickaxes in the Nether.
    expect(selectInventoryDiscard({ "minecraft:cobblestone": 40 })).toBeUndefined();
    expect(selectInventoryDiscard({ "minecraft:cobblestone": 289 })).toEqual({
      itemId: "minecraft:cobblestone",
      count: 64,
    });
    expect(selectInventoryDiscard({ "minecraft:cobblestone": 100 })).toEqual({
      itemId: "minecraft:cobblestone",
      count: 36,
    });
  });

  it("keeps the netherrack building reserve", () => {
    expect(selectInventoryDiscard({ "minecraft:netherrack": 64 })).toBeUndefined();
  });

  it("drops junk before building blocks", () => {
    expect(selectInventoryDiscard({ "minecraft:netherrack": 726, "minecraft:gravel": 15 })).toEqual(
      { itemId: "minecraft:gravel", count: 15 },
    );
  });
});

describe("inventory equipment retention", () => {
  it("discards obsolete tool tiers before the retained backup", () => {
    expect(
      selectRedundantEquipmentDiscard({
        "minecraft:wooden_pickaxe": 1,
        "minecraft:stone_pickaxe": 1,
        "minecraft:iron_pickaxe": 1,
      }),
    ).toEqual({
      itemId: "minecraft:wooden_pickaxe",
      count: 1,
    });
  });

  it("retains one best tool and one immediate-tier backup", () => {
    expect(
      selectRedundantEquipmentDiscard({
        "minecraft:stone_pickaxe": 1,
        "minecraft:iron_pickaxe": 1,
      }),
    ).toBeUndefined();
    expect(
      selectRedundantEquipmentDiscard({
        "minecraft:stone_pickaxe": 2,
        "minecraft:iron_pickaxe": 1,
      }),
    ).toEqual({
      itemId: "minecraft:stone_pickaxe",
      count: 1,
    });
  });

  it("retains one copy of singleton combat equipment", () => {
    expect(
      selectRedundantEquipmentDiscard({
        "minecraft:shield": 3,
        "minecraft:flint_and_steel": 2,
      }),
    ).toEqual({
      itemId: "minecraft:shield",
      count: 2,
    });
  });
});

async function runUntilExplorationStarts(options: {
  readonly driver: FakeBeatGameDriver;
  readonly store: InMemoryBeatGameCheckpointStore;
  readonly runId: string;
  readonly teamId: string;
}): Promise<{ readonly x: number; readonly z: number }> {
  const { driver, store, runId, teamId } = options;
  driver.xzPathResolver = (x, z, dimension, radius, policy) =>
    Effect.sync(() => {
      driver.xzPaths.push({ x, z, dimension, radius, policy });
    }).pipe(Effect.andThen(Effect.never));
  await Effect.runPromise(
    Effect.scoped(
      beatGameWithDriver(driver, {
        runId,
        team: { teamId },
        checkpointStore: store,
        strategy: { observationPollMs: 1 },
      }).pipe(
        Effect.flatMap((run) =>
          Effect.gen(function* () {
            while (driver.xzPaths.length === 0) {
              yield* Effect.sleep(1);
            }
            yield* run.stop;
            yield* run.awaitCompletion.pipe(Effect.result);
          }),
        ),
      ),
    ),
  );
  const path = driver.xzPaths[0];
  if (path === undefined) {
    throw new Error("Exploration did not start");
  }
  return path;
}

