function installNightBedTestWorld(driver: FakeBeatGameDriver): () => boolean {
  let bedPlaced = false;
  driver.blockQueryResolver = ({ center, radius, selector }) => {
    if (selector.blockIds?.includes("minecraft:water") === true) {
      return [];
    }
    if (selector.blockIds?.includes("minecraft:crafting_table") === true) {
      return [
        blockObservation(
          {
            x: 2,
            y: 64,
            z: 0,
            dimension: "minecraft:overworld",
          },
          { blockId: "minecraft:crafting_table" },
        ),
      ];
    }
    if (selector.blockIds?.includes("minecraft:white_bed") === true) {
      return bedPlaced
        ? [
            blockObservation(
              {
                x: 0,
                y: 64,
                z: 1,
                dimension: "minecraft:overworld",
              },
              {
                blockId: "minecraft:white_bed",
                diggable: true,
                replaceable: false,
                solid: false,
              },
            ),
          ]
        : [];
    }
    if (radius > 1) {
      return [
        airBlock(0, 64, 0),
        airBlock(0, 65, 0),
        airBlock(0, 64, 1),
        airBlock(0, 65, 1),
        airBlock(0, 64, 2),
        airBlock(0, 65, 2),
        stoneBlock(0, 63, 0),
        stoneBlock(0, 63, 1),
        stoneBlock(0, 63, 2),
      ];
    }
    if (
      bedPlaced &&
      Math.floor(center.x) === 0 &&
      Math.floor(center.y) === 64 &&
      Math.floor(center.z) === 1
    ) {
      return [
        blockObservation(
          {
            x: 0,
            y: 64,
            z: 1,
            dimension: "minecraft:overworld",
          },
          {
            blockId: "minecraft:white_bed",
            diggable: true,
            replaceable: false,
            solid: false,
          },
        ),
      ];
    }
    return [];
  };
  driver.actionObserver = (action) => {
    if (action.type === "place-block") {
      bedPlaced = true;
    }
  };
  return () => bedPlaced;
}

