  it("continues a food hunt from safe surface water when dry egress is blocked", async () => {
    const driver = new FakeBeatGameDriver();
    const preparedItems = {
      "minecraft:oak_log": 11,
      "minecraft:wooden_sword": 1,
    };
    driver.currentObservation = observation({
      air: 300,
      food: 15,
      health: 18.5,
      position: { x: 0.5, y: 62.1, z: 0.5 },
      counts: preparedItems,
    });
    const highShore = [-1, 0, 1].map((z) => ({
      x: 8,
      z,
      loaded: true,
      surfaceY: 68,
      blockId: "minecraft:grass_block",
      skyLight: 15,
      blockLight: 0,
    }));
    driver.surfaceQueryResolver = (_center, radius) => (radius > 4 ? highShore : []);
    driver.blockQueryResolver = (query) => {
      const position = {
        x: Math.floor(query.center.x),
        y: Math.floor(query.center.y),
        z: Math.floor(query.center.z),
        dimension: query.center.dimension,
      };
      if (query.selector.blockIds?.includes("minecraft:water") === true) {
        return position.y === 62
          ? [
              blockObservation(position, {
                blockId: "minecraft:water",
                diggable: false,
                replaceable: true,
              }),
            ]
          : [];
      }
      if (query.selector.blockIds !== undefined) {
        return [];
      }
      return [
        blockObservation(
          position,
          position.y === 68
            ? {
                blockId: "minecraft:grass_block",
                diggable: true,
                replaceable: false,
              }
            : {
                blockId: "minecraft:air",
                diggable: false,
                replaceable: true,
              },
        ),
      ];
    };
    const pig = {
      connectionEpoch: "epoch-1",
      networkId: 57,
      entityType: "minecraft:pig",
      position: {
        x: 2,
        y: 63,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      health: 10,
      observedAt: "2026-01-01T00:00:00.000Z",
    } satisfies BeatGameEntityObservation;
    driver.entityQueryResolver = (query) =>
      query.selector.entityTypes?.includes("minecraft:pig") === true ? [pig] : [];
    driver.pathResolver = (position, radius, policy) =>
      Effect.sync(() => {
        driver.paths.push({ position, radius, policy });
      }).pipe(
        Effect.andThen(
          Effect.fail(
            new BeatGameDriverError({
              operation: "pathfind",
              code: "unreachable",
              retryable: true,
              message: "The high bank has no traversable landing",
            }),
          ),
        ),
      );
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
      }).pipe(Effect.andThen(task.type === "attack-entity" ? Effect.never : Effect.void));
    const failures: string[] = [];

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            strategy: { observationPollMs: 1 },
          });
          yield* run.events.pipe(
            Stream.runForEach((event) =>
              event.type === "action-failed"
                ? Effect.sync(() => {
                    failures.push(event.detail ?? "");
                  })
                : Effect.void,
            ),
            Effect.forkScoped,
          );
          while (!driver.tasks.some((task) => task.type === "attack-entity")) {
            yield* Effect.sleep(1);
          }
          yield* run.stop;
        }),
      ),
    );

    expect(driver.tasks).toContainEqual(
      objectContaining({
        type: "attack-entity",
        target: objectContaining({ networkId: pig.networkId }),
      }),
    );
    const attackIndex = driver.tasks.findIndex((task) => task.type === "attack-entity");
    expect(driver.taskPolicies[attackIndex]).toMatchObject({
      avoidFluids: false,
    });
    expect(failures).not.toContain(
      "Interrupted for replanning: no observable progress while satisfying food-supply",
    );
  });

  it("keeps ascending before responding to an underwater threat", async () => {
    const driver = new FakeBeatGameDriver();
    const creeper = {
      connectionEpoch: "epoch-1",
      networkId: 54,
      entityType: "minecraft:creeper",
      position: {
        x: 2,
        y: 51,
        z: 0,
        dimension: "minecraft:overworld",
      },
      velocity: { x: 0, y: 0, z: 0 },
      alive: true,
      health: 20,
      observedAt: "2026-01-01T00:00:01.000Z",
    } satisfies BeatGameEntityObservation;
    driver.blockQueryResolver = (query) =>
      query.selector.blockIds?.includes("minecraft:water") === true &&
      driver.currentObservation.player.position.y < 52.5
        ? [
            blockObservation(
              {
                x: Math.floor(query.center.x),
                y: Math.floor(query.center.y),
                z: Math.floor(query.center.z),
                dimension: query.center.dimension,
              },
              {
                blockId: "minecraft:water",
                diggable: false,
                replaceable: true,
              },
            ),
          ]
        : [];
    driver.entityQueryResolver = (query) =>
      query.selector.categories?.includes(2) === true ? [creeper] : [];
    let ascending = false;
    let responseAir: number | undefined;
    driver.actionObserver = (action) => {
      if (action.type === "set-movement" && action.jump === true) {
        ascending = true;
      } else if (action.type === "reset-movement") {
        ascending = false;
      } else if (action.type === "attack-entity") {
        responseAir ??= driver.currentObservation.player.air;
      }
    };
    driver.observationResolver = () =>
      Effect.sync(() => {
        if (!ascending) {
          return driver.currentObservation;
        }
        driver.currentObservation = {
          ...driver.currentObservation,
          player: {
            ...driver.currentObservation.player,
            air: Math.min(
              driver.currentObservation.player.maxAir,
              driver.currentObservation.player.air + 40,
            ),
            position: {
              ...driver.currentObservation.player.position,
              y: driver.currentObservation.player.position.y + 0.75,
            },
          },
        };
        return driver.currentObservation;
      });
    driver.taskResolver = (task) =>
      Effect.sync(() => {
        driver.tasks.push(task);
        if (task.type === "flee") {
          responseAir ??= driver.currentObservation.player.air;
        }
      }).pipe(Effect.andThen(task.type === "collect-blocks" ? Effect.never : Effect.void));

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: { observationPollMs: 1 },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (!driver.tasks.some((task) => task.type === "collect-blocks")) {
                yield* Effect.sleep(1);
              }
              driver.currentObservation = observation({
                air: 100,
                health: 3,
                position: { x: 0, y: 51, z: 0 },
              });
              yield* sleepWhile(() => responseAir === undefined);
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    expect(responseAir).toBeGreaterThan(200);
    expect(driver.actions).toContainEqual({
      type: "set-movement",
      jump: true,
    });
    expect(driver.actions).toContainEqual({ type: "reset-movement" });
  });

