  it("retains portal progress after a local route miss", async () => {
    const driver = new FakeBeatGameDriver();
    const store = new InMemoryBeatGameCheckpointStore();
    const runId = "retain-portal-route-miss-run";
    const teamId = "retain-portal-route-miss-team";
    driver.currentObservation = observation({
      counts: {
        "minecraft:cobblestone": 20,
        "minecraft:cooked_beef": 8,
        "minecraft:flint_and_steel": 1,
        "minecraft:iron_pickaxe": 1,
        "minecraft:lava_bucket": 1,
        "minecraft:oak_log": 4,
        "minecraft:shield": 1,
        "minecraft:stone_sword": 1,
        "minecraft:water_bucket": 1,
      },
    });
    await Effect.runPromise(
      store.save(checkpoint(BeatGamePhase.ENTER_NETHER, { runId, teamId }), undefined),
    );
    let attempts = 0;
    const failures: string[] = [];

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            runId,
            team: { teamId },
            checkpointStore: store,
            strategy: { observationPollMs: 1 },
            hooks: {
              buildAndEnterNether: () =>
                Effect.sync(() => {
                  attempts += 1;
                  return attempts;
                }).pipe(
                  Effect.flatMap((attempt) =>
                    attempt === 1
                      ? Effect.fail(
                          new BeatGameDriverError({
                            operation: "pathfind",
                            code: "task_failed",
                            retryable: false,
                            message: "No route found to the goal!",
                          }),
                        )
                      : Effect.never,
                  ),
                ),
            },
          });
          yield* run.events.pipe(
            Stream.runForEach((event) => {
              const detail = event.type === "action-failed" ? event.detail : undefined;
              return detail === undefined
                ? Effect.void
                : Effect.sync(() => {
                    failures.push(detail);
                  });
            }),
            Effect.forkScoped,
          );
          yield* sleepWhile(() => attempts < 2).pipe(Effect.timeout("5 seconds"));
          yield* run.stop;
          yield* run.awaitCompletion.pipe(Effect.result);
        }),
      ),
    );

    const retained = await Effect.runPromise(store.load(runId));
    expect(attempts).toBe(2);
    expect(failures).toContainEqual(
      stringContaining("retained the portal workspace after a local route failure"),
    );
    expect(retained?.planner.status).not.toBe(BeatGameRunStatus.FAILED);
    expect(retained?.activeSkill).toMatchObject({
      kind: BeatGameDurableSkillKind.PORTAL_CONSTRUCTION,
      action: "build-and-enter-nether",
      status: BeatGameDurableSkillStatus.SUSPENDED,
    });
  });

