  it("keeps rotating resource exploration after blocked frontiers", async () => {
    const driver = new FakeBeatGameDriver();
    driver.currentObservation = observation({
      counts: {
        "minecraft:cobblestone": 20,
        "minecraft:oak_log": 8,
        "minecraft:stone_sword": 1,
      },
    });
    driver.xzPathResolver = (x, z, dimension, radius, policy) => {
      const dryAttempts = driver.xzPaths.filter(
        ({ policy: attemptedPolicy }) => attemptedPolicy.avoidFluids === true,
      ).length;
      const shouldFail = policy.avoidFluids !== true || dryAttempts < 2;
      return Effect.sync(() => {
        driver.xzPaths.push({ x, z, dimension, radius, policy });
      }).pipe(
        Effect.andThen(
          shouldFail
            ? Effect.fail(
                new BeatGameDriverError({
                  operation: "pathfindXZ",
                  code: "unreachable",
                  retryable: true,
                  message: "The frontier route made no progress",
                }),
              )
            : Effect.never,
        ),
      );
    };

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: { observationPollMs: 1 },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (
                driver.xzPaths.filter(({ policy }) => policy.avoidFluids === true).length < 3
              ) {
                yield* Effect.sleep(1);
              }
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    const dryPaths = driver.xzPaths.filter(({ policy }) => policy.avoidFluids === true);
    const attemptedTargets = dryPaths.slice(0, 3).map(({ x, z }) => ({
      x,
      z,
    }));
    expect(new Set(attemptedTargets.map(({ x, z }) => `${x}:${z}`)).size).toBeGreaterThanOrEqual(2);
    // A healthy food hunt hops one entity search radius per frontier leg.
    expect(attemptedTargets.every(({ x, z }) => Math.hypot(x, z) <= 48.01)).toBe(true);
  });

  it("segments a distant pending frontier into observed 32-block legs", async () => {
    const driver = new FakeBeatGameDriver();
    const store = new InMemoryBeatGameCheckpointStore();
    const runId = "segmented-exploration-frontier-run";
    const teamId = "segmented-exploration-frontier-team";
    const initial = checkpoint(BeatGamePhase.PREPARE_OVERWORLD, {
      runId,
      teamId,
    });
    await Effect.runPromise(
      store.save(
        {
          ...initial,
          memory: {
            ...initial.memory,
            explorationFrontiers: {
              "minecraft:overworld:find-logs": {
                progressVersion: 2,
                origin: driver.currentObservation.player.position,
                nextIndex: 9,
                targetAttempts: 0,
                totalAdvances: 8,
                lastPosition: driver.currentObservation.player.position,
              },
            },
          },
        },
        undefined,
      ),
    );
    driver.currentObservation = observation({
      counts: {
        "minecraft:cobblestone": 20,
        "minecraft:stone_sword": 1,
      },
    });
    driver.xzPathResolver = (x, z, dimension, radius, policy) =>
      Effect.sync(() => {
        driver.xzPaths.push({ x, z, dimension, radius, policy });
        driver.currentObservation = observation({
          position: { x, y: 64, z, dimension },
        });
      });

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          runId,
          team: { teamId },
          checkpointStore: store,
          strategy: { observationPollMs: 1 },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              yield* Effect.gen(function* () {
                while (driver.xzPaths.length < 4) {
                  yield* Effect.sleep(1);
                }
              }).pipe(
                Effect.timeoutOrElse({
                  duration: "5 seconds",
                  orElse: () =>
                    Effect.fail(
                      new ScenarioFailure({
                        message: "Distant exploration stopped making progress",
                      }),
                    ),
                }),
              );
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    let previous = { x: 0, z: 0 };
    const distances = driver.xzPaths.slice(0, 4).map(({ x, z }) => {
      const distance = Math.hypot(x - previous.x, z - previous.z);
      previous = { x, z };
      return distance;
    });
    expect(Math.max(...distances)).toBeCloseTo(32);
    expect(distances.every((distance) => distance <= 32.01)).toBe(true);
  });

