  it("selects the nearest fresh hunting target after every kill", async () => {
    const driver = new FakeBeatGameDriver();
    const preparedItems = {
      "minecraft:oak_log": 2,
      "minecraft:cobblestone": 20,
      "minecraft:stone_sword": 1,
      "minecraft:iron_ingot": 7,
      "minecraft:iron_pickaxe": 1,
      "minecraft:water_bucket": 1,
      "minecraft:flint_and_steel": 1,
      "minecraft:shield": 1,
    };
    const targets = [
      {
        connectionEpoch: "epoch-1",
        networkId: 1,
        entityType: "minecraft:cow",
        position: {
          x: 10,
          y: 64,
          z: 0,
          dimension: "minecraft:overworld",
        },
        velocity: { x: 0, y: 0, z: 0 },
        alive: true,
        observedAt: "2026-01-01T00:00:00.000Z",
      },
      {
        connectionEpoch: "epoch-1",
        networkId: 2,
        entityType: "minecraft:cow",
        position: {
          x: -11,
          y: 64,
          z: 0,
          dimension: "minecraft:overworld",
        },
        velocity: { x: 0, y: 0, z: 0 },
        alive: true,
        observedAt: "2026-01-01T00:00:00.000Z",
      },
      {
        connectionEpoch: "epoch-1",
        networkId: 3,
        entityType: "minecraft:cow",
        position: {
          x: 20,
          y: 64,
          z: 0,
          dimension: "minecraft:overworld",
        },
        velocity: { x: 0, y: 0, z: 0 },
        alive: true,
        observedAt: "2026-01-01T00:00:00.000Z",
      },
      {
        connectionEpoch: "epoch-1",
        networkId: 4,
        entityType: "minecraft:cow",
        position: {
          x: 1,
          y: 36,
          z: 0,
          dimension: "minecraft:overworld",
        },
        velocity: { x: 0, y: 0, z: 0 },
        alive: true,
        observedAt: "2026-01-01T00:00:00.000Z",
      },
    ] as const;
    driver.currentObservation = observation({ counts: preparedItems });
    driver.entityResults = targets;
    driver.xzPathResolver = (x, z, dimension, radius, policy) =>
      Effect.sync(() => {
        driver.xzPaths.push({ x, z, dimension, radius, policy });
        driver.currentObservation = observation({
          counts: preparedItems,
          position: {
            x,
            y: 64,
            z,
            dimension,
          },
        });
      });
    const attackOrder: number[] = [];
    driver.taskObserver = (task) => {
      if (task.type !== "attack-entity") {
        return;
      }
      attackOrder.push(task.target.networkId);
      const target = targets.find(({ networkId }) => networkId === task.target.networkId);
      if (target !== undefined) {
        driver.currentObservation = observation({
          counts: preparedItems,
          position: target.position,
        });
      }
    };

    await Effect.runPromise(
      Effect.scoped(
        beatGameWithDriver(driver, {
          strategy: { observationPollMs: 1 },
        }).pipe(
          Effect.flatMap((run) =>
            Effect.gen(function* () {
              while (attackOrder.length < 3) {
                yield* Effect.sleep(1);
              }
              yield* run.stop;
              yield* run.awaitCompletion.pipe(Effect.result);
            }),
          ),
        ),
      ),
    );

    expect(attackOrder).toEqual([1, 3, 2]);
    const huntQueries = driver.entityQueries.filter(
      ({ selector }) => selector.entityTypes?.includes("minecraft:cow") === true,
    );
    expect(huntQueries.slice(0, 3).map(({ origin }) => origin?.x)).toEqual([0, 10, 20]);
  });

