  it("selects a supported resource-search corridor before excavating", async () => {
    const driver = new FakeBeatGameDriver();
    const surfacePosition = {
      x: 24.5,
      y: 64,
      z: -12.5,
      dimension: "minecraft:overworld",
    } as const;
    const from = {
      x: Math.floor(surfacePosition.x),
      y: surfacePosition.y,
      z: Math.floor(surfacePosition.z),
      dimension: surfacePosition.dimension,
    };
    driver.currentObservation = observation({
      position: surfacePosition,
      counts: {
        "minecraft:white_bed": 1,
        "minecraft:cooked_beef": 12,
        "minecraft:oak_log": 8,
        "minecraft:cobblestone": 30,
        "minecraft:stone_sword": 1,
        "minecraft:stone_pickaxe": 1,
        "minecraft:water_bucket": 1,
      },
    });
    const dugBlocks = new Set<string>();
    driver.actionResolver = (action) =>
      Effect.sync(() => {
        if (action.type === "dig-block") {
          dugBlocks.add(`${action.position.x}:${action.position.y}:${action.position.z}`);
        }
        return {};
      });
    installStaircaseMovementSimulation(driver, from);
    driver.blockQueryResolver = ({ center, selector }) => {
      if (selector.blockIds?.includes("minecraft:iron_ore") === true) {
        return [];
      }
      const position = {
        x: Math.floor(center.x),
        y: Math.floor(center.y),
        z: Math.floor(center.z),
        dimension: center.dimension,
      };
      const positiveDepth = position.x - from.x;
      const unsupportedPositiveSupport =
        positiveDepth > 0 &&
        position.z === from.z &&
        (position.y === from.y - positiveDepth - 1 || position.y === from.y - positiveDepth - 2);
      const dug = dugBlocks.has(`${position.x}:${position.y}:${position.z}`);
      return [
        blockObservation(
          position,
          unsupportedPositiveSupport || dug
            ? {
                blockId: "minecraft:air",
                diggable: false,
                replaceable: true,
                solid: false,
              }
            : { blockId: "minecraft:stone" },
        ),
      ];
    };

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            strategy: { observationPollMs: 1 },
          });
          while (driver.currentObservation.player.position.y > 52) {
            yield* Effect.sleep(1);
          }
          yield* run.stop;
        }),
      ),
    );

    expect(driver.paths).toContainEqual(
      objectContaining({
        position: objectContaining({ x: 23.5, y: 63, z: -12.5 }),
      }),
    );
    expect(driver.paths).not.toContainEqual(
      objectContaining({
        position: objectContaining({ x: 25.5, y: 63, z: -12.5 }),
      }),
    );
    expect(
      driver.actions.some((action) => action.type === "dig-block" && action.position.x > from.x),
    ).toBe(false);
  });

