  it.each([
    {
      name: "only raw food at the meal threshold",
      food: 14,
      health: 20,
      foodItems: { "minecraft:beef": 1 },
    },
    {
      name: "low health and no food",
      food: 17,
      health: 13,
      foodItems: { "minecraft:red_mushroom": 3 },
    },
    // As in a live run whose trip back for food was interrupted for the
    // hunger that sent it, after it had eaten its last raw pork.
    {
      name: "urgent hunger and no food",
      food: 9,
      health: 20,
      foodItems: {},
    },
  ])("keeps walking back to a portal with $name", async ({ food, health, foodItems }) => {
    const driver = new FakeBeatGameDriver();
    const store = new InMemoryBeatGameCheckpointStore();
    const runId = "raw-food-portal-trip-run";
    const teamId = "raw-food-portal-trip-team";
    const netherPortal = blockObservation(
      { x: 55, y: 91, z: -6, dimension: "minecraft:the_nether" },
      { blockId: "minecraft:nether_portal", diggable: false },
    );
    const counts = {
      ...foodItems,
      "minecraft:dark_oak_log": 12,
      "minecraft:shield": 1,
      "minecraft:stone_pickaxe": 1,
      "minecraft:wooden_sword": 1,
    };
    driver.currentObservation = observation({
      dimension: "minecraft:the_nether",
      position: { x: 0.5, y: 64, z: 0.5 },
      food: 15,
      health,
      counts,
    });
    let interruptedTrips = 0;
    driver.xzPathResolver = (x, z, dimension, radius, policy) =>
      Effect.sync(() => {
        driver.xzPaths.push({ x, z, dimension, radius, policy });
        driver.currentObservation = observation({
          dimension: "minecraft:the_nether",
          position: { x: 0.5, y: 64, z: 0.5 },
          food,
          health,
          counts,
        });
      }).pipe(
        Effect.andThen(Effect.never),
        Effect.onInterrupt(() =>
          Effect.sync(() => {
            interruptedTrips += 1;
          }),
        ),
      );
    const initial = checkpoint(BeatGamePhase.PREPARE_OVERWORLD, { runId, teamId });
    await Effect.runPromise(
      store.save(
        {
          ...initial,
          memory: {
            ...initial.memory,
            portals: [
              {
                key: "portal:nether",
                value: netherPortal,
                observedAt: netherPortal.observedAt,
                confidence: 1,
              },
            ],
          },
        },
        undefined,
      ),
    );

    await Effect.runPromise(
      Effect.scoped(
        Effect.gen(function* () {
          const run = yield* beatGameWithDriver(driver, {
            runId,
            team: { teamId },
            checkpointStore: store,
            strategy: { observationPollMs: 1 },
          });
          const startedActions: string[] = [];
          yield* run.events.pipe(
            Stream.runForEach((event) =>
              Effect.sync(() => {
                if (event.type === "action-started") {
                  startedActions.push(event.action);
                }
              }),
            ),
            Effect.forkScoped,
          );
          while (driver.xzPaths.length === 0) {
            yield* Effect.sleep(1);
          }
          yield* Effect.sleep(200);
          expect(interruptedTrips).toBe(0);
          expect(driver.xzPaths).toHaveLength(1);
          expect(new Set(startedActions)).toEqual(new Set(["return-through-portal"]));
          yield* run.stop;
        }).pipe(
          Effect.timeoutOrElse({
            duration: "5 seconds",
            orElse: () =>
              Effect.fail(
                new ScenarioFailure({ message: "The bot never walked toward the portal" }),
              ),
          }),
        ),
      ),
    );
  });

